// =====================================================================
// HubSpot Deal Aggregator
// n8n-hubspot-deal-stage-probability-weighted-forecast-bot
// dhRobin Systems · MIT License · Provided as-is, see DISCLAIMER.md
// ---------------------------------------------------------------------
// Mode: Run Once for All Items
// Live mode:
//   1. GET  /crm/v3/pipelines/deals            → stages, probabilities, closed flags
//   2. POST /crm/v3/objects/deals/search       → open deals in the forecast horizon (paged)
//   3. POST /crm/v3/objects/deals/search       → closed-won deals this fiscal quarter (paged)
//   4. GET  /crm/v3/owners (optional)          → owner display names
// Sandbox mode: returns a fixed, fictional dataset and calls nothing.
// Output: ONE item { meta, periods, pipelines, deals, closedWon, owners, previousSnapshot }
// =====================================================================

// ---------- 1. Configuration ----------
const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const isOn = (key) => env(key, 'true').toLowerCase() !== 'false';
const csv  = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const int  = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };

const HUBSPOT_API_BASE = 'https://api.hubapi.com'; // fixed: the token is never sent anywhere else
const CONFIG = {
  SANDBOX_MODE:            isOn('SANDBOX_MODE'),
  HUBSPOT_ACCESS_TOKEN:    env('HUBSPOT_ACCESS_TOKEN', ''),
  PIPELINE_IDS:            csv('PIPELINE_IDS', '').filter((p) => /^[A-Za-z0-9_-]{1,64}$/.test(p)),
  HORIZON_QUARTERS:        Math.min(8, Math.max(1, int('HORIZON_QUARTERS', 2))),
  FISCAL_YEAR_START_MONTH: Math.min(12, Math.max(1, int('FISCAL_YEAR_START_MONTH', 1))),
  MAX_DEALS:               Math.min(10000, Math.max(100, int('MAX_DEALS', 5000))),
  PAGE_DELAY_MS:           Math.max(0, int('PAGE_DELAY_MS', 250)),
  INCLUDE_OWNER_NAMES:     isOn('INCLUDE_OWNER_NAMES'),
  AMOUNT_PROPERTY:         /^[a-z0-9_]{1,100}$/.test(env('AMOUNT_PROPERTY', 'amount_in_home_currency')) ? env('AMOUNT_PROPERTY', 'amount_in_home_currency') : 'amount_in_home_currency',
  REPORT_DATE_OVERRIDE:    env('REPORT_DATE_OVERRIDE', ''),
};
const SAMPLE_AS_OF = '2026-11-16T08:00:00.000Z'; // fixed so sandbox output is reproducible

const looksPlaceholder = (v) => /YOUR_|PLACEHOLDER|CHANGE_ME|REPLACE_/i.test(String(v || ''));
if (!CONFIG.SANDBOX_MODE && (!CONFIG.HUBSPOT_ACCESS_TOKEN || looksPlaceholder(CONFIG.HUBSPOT_ACCESS_TOKEN))) {
  throw new Error('SANDBOX_MODE=false requires a real HUBSPOT_ACCESS_TOKEN environment variable.');
}

// ---------- 2. Period maths (UTC, fiscal-year aware) ----------
const asOfRaw = CONFIG.REPORT_DATE_OVERRIDE || (CONFIG.SANDBOX_MODE ? SAMPLE_AS_OF : new Date().toISOString());
const asOf = new Date(asOfRaw);
if (isNaN(asOf.getTime())) throw new Error('REPORT_DATE_OVERRIDE is not a valid ISO date.');

const utc = (y, m, d = 1) => new Date(Date.UTC(y, m, d));            // m is 0-based and may overflow
const addMonths = (date, n) => utc(date.getUTCFullYear(), date.getUTCMonth() + n, date.getUTCDate());
function fiscalQuarter(date, offsetQuarters = 0) {
  const fsm = CONFIG.FISCAL_YEAR_START_MONTH - 1;                    // 0-based fiscal start month
  const monthsIntoFy = (date.getUTCMonth() - fsm + 12) % 12;
  const fyStartYear = date.getUTCMonth() >= fsm ? date.getUTCFullYear() : date.getUTCFullYear() - 1;
  const qIndex = Math.floor(monthsIntoFy / 3) + offsetQuarters;      // may exceed 3 for later quarters
  const start = utc(fyStartYear, fsm + qIndex * 3, 1);
  const end = new Date(addMonths(start, 3).getTime() - 1);
  const startMonthsIntoFy = (start.getUTCMonth() - fsm + 12) % 12;
  const startFyYear = start.getUTCMonth() >= fsm ? start.getUTCFullYear() : start.getUTCFullYear() - 1;
  const fyLabel = CONFIG.FISCAL_YEAR_START_MONTH === 1 ? startFyYear : startFyYear + 1;
  return { label: `Q${Math.floor(startMonthsIntoFy / 3) + 1} FY${fyLabel}`, start: start.toISOString(), end: end.toISOString() };
}
function isoWeekKey(date) {
  const d = utc(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate());
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const yearStart = utc(d.getUTCFullYear(), 0, 1);
  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
}
const todayStart = utc(asOf.getUTCFullYear(), asOf.getUTCMonth(), asOf.getUTCDate());
const monthStart = utc(asOf.getUTCFullYear(), asOf.getUTCMonth(), 1);
const periods = {
  asOf: asOf.toISOString(),
  today: todayStart.toISOString(),
  weekKey: isoWeekKey(asOf),
  month: { start: monthStart.toISOString(), end: new Date(addMonths(monthStart, 1).getTime() - 1).toISOString() },
  quarter: fiscalQuarter(asOf, 0),
  nextQuarter: fiscalQuarter(asOf, 1),
  horizonEnd: fiscalQuarter(asOf, CONFIG.HORIZON_QUARTERS - 1).end,
  horizonQuarters: CONFIG.HORIZON_QUARTERS,
  fiscalYearStartMonth: CONFIG.FISCAL_YEAR_START_MONTH,
};

// ---------- 3. Helpers ----------
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const redact = (t) => String(t || '').replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]').replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]').slice(0, 200);
const numOrNull = (v) => { if (v === null || v === undefined || v === '') return null; const n = Number(v); return Number.isFinite(n) ? n : null; };
const isoOrNull = (v) => { if (!v) return null; const d = /^\d+$/.test(String(v)) ? new Date(Number(v)) : new Date(String(v)); return isNaN(d.getTime()) ? null : d.toISOString(); };

const helpers = this.helpers;
async function hubspot(method, path, body) {
  if (!helpers || typeof helpers.httpRequest !== 'function') throw new Error('this.helpers.httpRequest is not available in this n8n version.');
  const options = { method, url: `${HUBSPOT_API_BASE}${path}`, json: true, timeout: 20000,
    headers: { Authorization: `Bearer ${CONFIG.HUBSPOT_ACCESS_TOKEN}`, 'Content-Type': 'application/json' } };
  if (body) options.body = body;
  for (let attempt = 1; attempt <= 4; attempt++) {
    try { return await helpers.httpRequest(options); }
    catch (err) {
      const status = Number(err?.httpCode || err?.statusCode || err?.response?.status) || null;
      if ((status === 429 || (status && status >= 500)) && attempt < 4) { await sleep(1500 * attempt); continue; }
      // Sanitised: endpoint path and status only. The full error never reaches logs or Slack.
      throw new Error(`HubSpot ${method} ${path.split('?')[0]} failed (HTTP ${status || 'n/a'}): ${redact(err?.message)}`);
    }
  }
}

async function searchAll(body) {
  const out = [];
  let after;
  do {
    const res = await hubspot('POST', '/crm/v3/objects/deals/search', { ...body, limit: 200, ...(after ? { after } : {}) });
    for (const r of (res && res.results) || []) out.push(r);
    after = res && res.paging && res.paging.next && res.paging.next.after;
    if (out.length >= CONFIG.MAX_DEALS) { after = undefined; }
    if (after && CONFIG.PAGE_DELAY_MS) await sleep(CONFIG.PAGE_DELAY_MS);
  } while (after);
  return out.slice(0, CONFIG.MAX_DEALS);
}

const DEAL_PROPERTIES = ['dealname', 'amount', 'amount_in_home_currency', CONFIG.AMOUNT_PROPERTY, 'closedate', 'dealstage', 'pipeline',
  'hubspot_owner_id', 'hs_deal_stage_probability', 'hs_lastmodifieddate', 'notes_last_updated', 'createdate'];

function normalizeDeal(r) {
  const p = (r && r.properties) || {};
  const amount = numOrNull(p[CONFIG.AMOUNT_PROPERTY]) ?? numOrNull(p.amount);
  return {
    id: String(r.id),
    name: String(p.dealname || `Deal ${r.id}`).slice(0, 120),
    amount,
    closeDate: isoOrNull(p.closedate),
    pipelineId: p.pipeline ? String(p.pipeline) : null,
    stageId: p.dealstage ? String(p.dealstage) : null,
    ownerId: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    dealProbability: numOrNull(p.hs_deal_stage_probability),
    lastModified: isoOrNull(p.hs_lastmodifieddate),
    lastActivity: isoOrNull(p.notes_last_updated),
  };
}

// ---------- 4. Sandbox dataset (fictional) ----------
function sampleDataset() {
  const st = (id, label, probability, displayOrder, isClosed = false) => ({ id, label, probability, displayOrder, isClosed });
  const pipelines = [
    { id: 'default', label: 'New Business', displayOrder: 0, stages: [
      st('appointmentscheduled', 'Discovery', 0.2, 0), st('qualifiedtobuy', 'Qualified', 0.4, 1),
      st('presentationscheduled', 'Demo / Solution', 0.6, 2), st('decisionmakerboughtin', 'Decision Maker Bought-In', 0.8, 3),
      st('contractsent', 'Contract Sent', 0.9, 4), st('closedwon', 'Closed Won', 1, 5, true), st('closedlost', 'Closed Lost', 0, 6, true) ] },
    { id: 'PIPELINE_ID_RENEWALS', label: 'Renewals', displayOrder: 1, stages: [
      st('STAGE_ID_RENEWAL_OPEN', 'Renewal Open', 0.5, 0), st('STAGE_ID_RENEWAL_NEGOTIATION', 'Negotiation', 0.75, 1),
      st('STAGE_ID_RENEWAL_COMMITTED', 'Verbally Committed', 0.9, 2), st('STAGE_ID_RENEWAL_WON', 'Renewed', 1, 3, true), st('STAGE_ID_RENEWAL_LOST', 'Churned', 0, 4, true) ] },
  ];
  const d = (id, name, amount, closeDate, pipelineId, stageId, ownerId, lastModified, dealProbability = null) =>
    ({ id, name: `${name} (fictional)`, amount, closeDate: closeDate ? `${closeDate}T00:00:00.000Z` : null, pipelineId, stageId, ownerId, dealProbability, lastModified: `${lastModified}T12:00:00.000Z`, lastActivity: null });
  const deals = [
    d('SMP-1001', 'Alpha Ltd - Platform',     120000, '2026-12-15', 'default', 'contractsent',          'OWNER_ID_1', '2026-11-13'),
    d('SMP-1002', 'Bravo Inc - Expansion',     85000, '2026-11-28', 'default', 'decisionmakerboughtin', 'OWNER_ID_2', '2026-11-12'),
    d('SMP-1003', 'Charlie GmbH - Pilot',      40000, '2026-11-05', 'default', 'presentationscheduled', 'OWNER_ID_1', '2026-10-01'),
    d('SMP-1004', 'Delta Co - Enterprise',    250000, '2026-12-20', 'default', 'qualifiedtobuy',        'OWNER_ID_3', '2026-11-10'),
    d('SMP-1005', 'Echo Partners - Starter',   18000, '2026-12-05', 'default', 'appointmentscheduled',  'OWNER_ID_2', '2026-11-14'),
    d('SMP-1006', 'Foxtrot Labs - Platform',   95000, '2027-01-30', 'default', 'presentationscheduled', 'OWNER_ID_3', '2026-11-09'),
    d('SMP-1007', 'Golf Health - Analytics',   60000, '2027-02-15', 'default', 'qualifiedtobuy',        'OWNER_ID_1', '2026-10-20'),
    d('SMP-1008', 'Hotel Retail - Rollout',     null, '2026-12-10', 'default', 'appointmentscheduled',  'OWNER_ID_2', '2026-11-11'),
    d('SMP-1009', 'India Logistics - Suite',   70000,         null, 'default', 'qualifiedtobuy',        'OWNER_ID_3', '2026-11-02'),
    d('SMP-1010', 'Juliet Media - Add-on',     22000, '2026-11-30', 'default', 'contractsent',          'OWNER_ID_1', '2026-11-15'),
    d('SMP-2001', 'Kilo Systems - Renewal',    48000, '2026-12-31', 'PIPELINE_ID_RENEWALS', 'STAGE_ID_RENEWAL_NEGOTIATION', 'OWNER_ID_2', '2026-11-06'),
    d('SMP-2002', 'Lima Energy - Renewal',     36000, '2026-11-20', 'PIPELINE_ID_RENEWALS', 'STAGE_ID_RENEWAL_COMMITTED',   'OWNER_ID_3', '2026-11-13'),
    d('SMP-2003', 'Mike Foods - Renewal',      30000, '2027-03-15', 'PIPELINE_ID_RENEWALS', 'STAGE_ID_RENEWAL_OPEN',        'OWNER_ID_1', '2026-11-03'),
  ];
  const closedWon = [
    d('SMP-3001', 'Oscar Bank - Platform',    110000, '2026-10-14', 'default', 'closedwon', 'OWNER_ID_1', '2026-10-14'),
    d('SMP-3002', 'Papa Telecom - Renewal',    42000, '2026-10-28', 'PIPELINE_ID_RENEWALS', 'STAGE_ID_RENEWAL_WON', 'OWNER_ID_2', '2026-10-28'),
    d('SMP-3003', 'Quebec Edu - Starter',      15000, '2026-11-09', 'default', 'closedwon', 'OWNER_ID_3', '2026-11-09'),
  ];
  const owners = { OWNER_ID_1: 'Owner A (placeholder)', OWNER_ID_2: 'Owner B (placeholder)', OWNER_ID_3: 'Owner C (placeholder)' };
  const previousSnapshot = { weekKey: '2026-W46', asOf: '2026-11-09T08:00:00.000Z', quarterLabel: 'Q4 FY2026',
    quarterWeighted: 372500, openAmount: 812000, openCount: 12, closedWonQTD: 152000 };
  return { pipelines, deals, closedWon, owners, previousSnapshot, sampleTarget: 450000 };
}

// ---------- 5. Live loaders ----------
async function loadPipelines() {
  const res = await hubspot('GET', '/crm/v3/pipelines/deals');
  return ((res && res.results) || []).filter((p) => !p.archived).map((p) => ({
    id: String(p.id), label: String(p.label || p.id), displayOrder: Number(p.displayOrder) || 0,
    stages: (p.stages || []).filter((s) => !s.archived).map((s) => ({
      id: String(s.id), label: String(s.label || s.id), displayOrder: Number(s.displayOrder) || 0,
      probability: Math.min(1, Math.max(0, Number(s.metadata && s.metadata.probability) || 0)),
      isClosed: String(s.metadata && s.metadata.isClosed) === 'true',
    })),
  }));
}
async function loadOwners() {
  const owners = {};
  let after;
  do {
    const res = await hubspot('GET', `/crm/v3/owners?limit=500${after ? `&after=${encodeURIComponent(after)}` : ''}`);
    for (const o of (res && res.results) || []) owners[String(o.id)] = [o.firstName, o.lastName].filter(Boolean).join(' ') || `Owner ${o.id}`;
    after = res && res.paging && res.paging.next && res.paging.next.after;
  } while (after);
  return owners;
}

// ---------- 6. Main ----------
let dataset; let source;
if (CONFIG.SANDBOX_MODE) {
  dataset = sampleDataset();
  source = 'sandbox_sample';
  // Mirror the live search filter: drop open deals that close after the horizon.
  dataset.deals = dataset.deals.filter((x) => !x.closeDate || x.closeDate <= periods.horizonEnd);
} else {
  let pipelines = await loadPipelines();
  if (CONFIG.PIPELINE_IDS.length) pipelines = pipelines.filter((p) => CONFIG.PIPELINE_IDS.includes(p.id));
  if (!pipelines.length) throw new Error('No deal pipelines matched PIPELINE_IDS.');
  const closedStageIds = pipelines.flatMap((p) => p.stages.filter((s) => s.isClosed).map((s) => s.id));
  const wonStageIds = pipelines.flatMap((p) => p.stages.filter((s) => s.isClosed && s.probability >= 1).map((s) => s.id));
  const pipelineFilter = { propertyName: 'pipeline', operator: 'IN', values: pipelines.map((p) => p.id) };
  const openStage = closedStageIds.length ? [{ propertyName: 'dealstage', operator: 'NOT_IN', values: closedStageIds }] : [];
  const horizonMs = String(new Date(periods.horizonEnd).getTime());
  const sorts = [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }];

  const openRaw = await searchAll({
    filterGroups: [
      { filters: [pipelineFilter, ...openStage, { propertyName: 'closedate', operator: 'LTE', value: horizonMs }] },
      { filters: [pipelineFilter, ...openStage, { propertyName: 'closedate', operator: 'NOT_HAS_PROPERTY' }] },
    ],
    properties: [...new Set(DEAL_PROPERTIES)], sorts,
  });
  const wonRaw = wonStageIds.length ? await searchAll({
    filterGroups: [{ filters: [pipelineFilter, { propertyName: 'dealstage', operator: 'IN', values: wonStageIds },
      { propertyName: 'closedate', operator: 'GTE', value: String(new Date(periods.quarter.start).getTime()) },
      { propertyName: 'closedate', operator: 'LTE', value: String(asOf.getTime()) }] }],
    properties: [...new Set(DEAL_PROPERTIES)], sorts,
  }) : [];

  let owners = {};
  if (CONFIG.INCLUDE_OWNER_NAMES) { try { owners = await loadOwners(); } catch (e) { owners = {}; } } // optional scope

  const sd = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
  const history = Object.values(sd.snapshots || {}).filter((s) => s && s.weekKey !== periods.weekKey).sort((a, b) => String(b.weekKey).localeCompare(String(a.weekKey)));

  dataset = { pipelines, deals: openRaw.map(normalizeDeal), closedWon: wonRaw.map(normalizeDeal), owners, previousSnapshot: history[0] || null, sampleTarget: null };
  source = 'hubspot_live';
}

return [{ json: {
  meta: {
    source,
    generatedAt: new Date().toISOString(),
    dealCount: dataset.deals.length,
    closedWonCount: dataset.closedWon.length,
    truncated: dataset.deals.length >= CONFIG.MAX_DEALS,
    amountProperty: CONFIG.AMOUNT_PROPERTY,
    sampleTarget: dataset.sampleTarget,
  },
  periods,
  pipelines: dataset.pipelines,
  deals: dataset.deals,
  closedWon: dataset.closedWon,
  owners: dataset.owners,
  previousSnapshot: dataset.previousSnapshot,
} }];

// =====================================================================
// Forecast Calculator
// n8n-hubspot-deal-stage-probability-weighted-forecast-bot
// dhRobin Systems · MIT License · Provided as-is, see DISCLAIMER.md
// ---------------------------------------------------------------------
// Mode: Run Once for All Items · pure calculation, no network calls
//   weighted(deal)      = amount × probability
//   expected (E)        = Σ amount × p
//   variance (Var)      = Σ amount² × p × (1 − p)     (independent Bernoulli outcomes)
//   P10 / P90 range     = E ∓ 1.2816 × √Var            (normal approximation, floored at 0)
//   projected quarter   = closed-won QTD + E(current-quarter open deals)
//   coverage ratio      = open quarter pipeline ÷ (target − closed-won QTD)
// =====================================================================

const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const num = (key, fallback) => { const n = parseFloat(env(key, String(fallback))); return Number.isFinite(n) ? n : fallback; };
const int = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };

const data = $input.first().json;

let overrides = {};
const rawOverrides = env('STAGE_PROBABILITY_OVERRIDES_JSON', '');
if (rawOverrides) {
  try { overrides = JSON.parse(rawOverrides); } catch (e) { throw new Error('STAGE_PROBABILITY_OVERRIDES_JSON is not valid JSON.'); }
  if (!overrides || typeof overrides !== 'object' || Array.isArray(overrides)) throw new Error('STAGE_PROBABILITY_OVERRIDES_JSON must be an object of { stageId: probability }.');
}

const targetEnv = env('QUARTER_TARGET', '');
const CONFIG = {
  PROBABILITY_SOURCE: env('PROBABILITY_SOURCE', 'stage').toLowerCase(),             // stage | deal_property
  COMMIT_PROBABILITY: Math.min(1, Math.max(0, num('COMMIT_PROBABILITY', 0.8))),
  STALE_DAYS:         Math.max(1, int('STALE_DAYS', 21)),
  PAST_DUE_TREATMENT: env('PAST_DUE_TREATMENT', 'current_quarter').toLowerCase(),    // current_quarter | exclude
  TOP_DEALS_COUNT:    Math.min(10, Math.max(0, int('TOP_DEALS_COUNT', 5))),
  TOP_OWNERS_COUNT:   Math.min(15, Math.max(0, int('TOP_OWNERS_COUNT', 5))),
  QUARTER_TARGET:     targetEnv !== '' && Number.isFinite(Number(targetEnv)) ? Number(targetEnv) : (data.meta && data.meta.sampleTarget) || null,
};
const Z90 = 1.2816;
const round = (n) => Math.round(n * 100) / 100;
const ratio = (n) => Math.round(n * 10000) / 10000; // ratios keep 4 decimals
const clamp01 = (n) => Math.min(1, Math.max(0, n));
const p = data.periods;
const t = (iso) => (iso ? new Date(iso).getTime() : null);

// ---------- Stage index ----------
const stageIndex = {};
for (const pl of data.pipelines || []) {
  for (const s of pl.stages || []) {
    stageIndex[s.id] = { pipelineId: pl.id, pipelineLabel: pl.label, pipelineOrder: pl.displayOrder, stageLabel: s.label, order: s.displayOrder, probability: s.probability, isClosed: s.isClosed };
  }
}

// ---------- Per-deal enrichment ----------
const today = t(p.today); const monthEnd = t(p.month.end);
const qStart = t(p.quarter.start); const qEnd = t(p.quarter.end);
const nqStart = t(p.nextQuarter.start); const nqEnd = t(p.nextQuarter.end);
const staleCutoff = t(p.asOf) - CONFIG.STALE_DAYS * 86400000;
const owners = data.owners || {};

const enriched = (data.deals || []).map((d) => {
  const stage = stageIndex[d.stageId] || null;
  const flags = [];
  if (!stage) flags.push('unknown_stage');
  if (stage && stage.isClosed) flags.push('closed_stage_in_open_set');
  let probability;
  let probabilitySource;
  if (d.stageId && overrides[d.stageId] !== undefined && Number.isFinite(Number(overrides[d.stageId]))) { probability = clamp01(Number(overrides[d.stageId])); probabilitySource = 'override'; }
  else if (CONFIG.PROBABILITY_SOURCE === 'deal_property' && Number.isFinite(d.dealProbability)) { probability = clamp01(d.dealProbability); probabilitySource = 'deal_property'; }
  else if (stage) { probability = clamp01(stage.probability); probabilitySource = 'stage'; }
  else { probability = 0; probabilitySource = 'unknown_stage_zero'; }

  const amount = Number.isFinite(d.amount) ? Math.max(0, d.amount) : 0;
  if (!Number.isFinite(d.amount)) flags.push('missing_amount');
  const close = t(d.closeDate);
  let period;
  if (close === null) { period = 'no_close_date'; flags.push('missing_close_date'); }
  else if (close < today) { period = 'past_due'; flags.push('past_due'); }
  else if (close <= monthEnd) period = 'this_month';
  else if (close <= qEnd) period = 'this_quarter_later';
  else if (close >= nqStart && close <= nqEnd) period = 'next_quarter';
  else period = 'later';
  const lastTouch = Math.max(t(d.lastActivity) || 0, t(d.lastModified) || 0);
  if (lastTouch && lastTouch < staleCutoff) flags.push('stale');
  const inQuarter = period === 'this_month' || period === 'this_quarter_later' || (period === 'past_due' && CONFIG.PAST_DUE_TREATMENT === 'current_quarter');

  return {
    id: d.id, name: d.name, amount, probability, probabilitySource, weighted: amount * probability,
    pipelineId: stage ? stage.pipelineId : d.pipelineId, pipelineLabel: stage ? stage.pipelineLabel : (d.pipelineId || 'Unknown'),
    stageId: d.stageId, stageLabel: stage ? stage.stageLabel : (d.stageId || 'Unknown'), stageOrder: stage ? stage.order : 999,
    pipelineOrder: stage ? stage.pipelineOrder : 999,
    ownerId: d.ownerId, ownerName: (d.ownerId && owners[d.ownerId]) || (d.ownerId ? `Owner ${d.ownerId}` : 'Unassigned'),
    closeDate: d.closeDate, period, inQuarter, flags,
  };
}).filter((d) => !d.flags.includes('closed_stage_in_open_set'));

// ---------- Aggregation helpers ----------
const agg = (list) => {
  const amount = list.reduce((s, d) => s + d.amount, 0);
  const weighted = list.reduce((s, d) => s + d.weighted, 0);
  const variance = list.reduce((s, d) => s + d.amount * d.amount * d.probability * (1 - d.probability), 0);
  const sigma = Math.sqrt(variance);
  return { count: list.length, amount: round(amount), weighted: round(weighted), sigma: round(sigma),
    p10: round(Math.max(0, weighted - Z90 * sigma)), p90: round(Math.min(amount, weighted + Z90 * sigma)) };
};
const groupBy = (list, keyFn) => list.reduce((m, d) => { const k = keyFn(d); (m[k] = m[k] || []).push(d); return m; }, {});

// ---------- Headline metrics ----------
const quarterDeals = enriched.filter((d) => d.inQuarter);
const quarterAgg = agg(quarterDeals);
const commit = round(quarterDeals.filter((d) => d.probability >= CONFIG.COMMIT_PROBABILITY).reduce((s, d) => s + d.amount, 0));
const closedWonQTD = round((data.closedWon || []).reduce((s, d) => s + (Number.isFinite(d.amount) ? d.amount : 0), 0));
const target = CONFIG.QUARTER_TARGET;
const projected = round(closedWonQTD + quarterAgg.weighted);
const remaining = target !== null ? target - closedWonQTD : null;

const quarter = {
  label: p.quarter.label, start: p.quarter.start, end: p.quarter.end,
  ...quarterAgg,
  bestCase: round(closedWonQTD + quarterAgg.amount),
  commit: round(closedWonQTD + commit),
  closedWonQTD,
  closedWonCount: (data.closedWon || []).length,
  projected,
  projectedP10: round(closedWonQTD + quarterAgg.p10),
  projectedP90: round(closedWonQTD + quarterAgg.p90),
  target,
  attainment: target ? ratio(closedWonQTD / target) : null,
  projectedAttainment: target ? ratio(projected / target) : null,
  gapToTarget: target !== null ? round(target - projected) : null,
  coverage: remaining !== null && remaining > 0 ? round(quarterAgg.amount / remaining) : null,
  targetAlreadyMet: remaining !== null && remaining <= 0,
  daysLeft: Math.max(0, Math.ceil((qEnd - t(p.asOf)) / 86400000)),
};

const allAgg = agg(enriched);
const nextQuarter = { label: p.nextQuarter.label, ...agg(enriched.filter((d) => d.period === 'next_quarter')) };

const PERIOD_ORDER = [
  ['past_due', 'Past due'], ['this_month', 'This month'], ['this_quarter_later', `Rest of ${p.quarter.label}`],
  ['next_quarter', p.nextQuarter.label], ['later', 'Later in horizon'], ['no_close_date', 'No close date'],
];
const periodGroups = groupBy(enriched, (d) => d.period);
const byPeriod = PERIOD_ORDER.map(([key, label]) => ({ key, label, ...agg(periodGroups[key] || []) })).filter((r) => r.count > 0);

const stageGroups = groupBy(enriched, (d) => `${d.pipelineId}::${d.stageId}`);
const byStage = Object.values(stageGroups).map((list) => ({
  pipelineLabel: list[0].pipelineLabel, stageLabel: list[0].stageLabel, pipelineOrder: list[0].pipelineOrder, stageOrder: list[0].stageOrder,
  probability: list[0].probability, ...agg(list),
})).sort((a, b) => a.pipelineOrder - b.pipelineOrder || a.stageOrder - b.stageOrder);

const pipelineGroups = groupBy(enriched, (d) => d.pipelineId);
const byPipeline = Object.values(pipelineGroups).map((list) => ({
  pipelineLabel: list[0].pipelineLabel, pipelineOrder: list[0].pipelineOrder, ...agg(list),
  quarterWeighted: round(list.filter((d) => d.inQuarter).reduce((s, d) => s + d.weighted, 0)),
})).sort((a, b) => a.pipelineOrder - b.pipelineOrder);

const ownerGroups = groupBy(quarterDeals, (d) => d.ownerName);
const byOwner = Object.entries(ownerGroups).map(([ownerName, list]) => ({ ownerName, ...agg(list) }))
  .sort((a, b) => b.weighted - a.weighted).slice(0, CONFIG.TOP_OWNERS_COUNT);

const topDeals = [...quarterDeals].sort((a, b) => b.weighted - a.weighted).slice(0, CONFIG.TOP_DEALS_COUNT).map((d) => ({
  id: d.id, name: d.name, amount: d.amount, probability: d.probability, weighted: round(d.weighted),
  closeDate: d.closeDate, stageLabel: d.stageLabel, pipelineLabel: d.pipelineLabel, ownerName: d.ownerName, flags: d.flags,
}));
const top3Weighted = [...quarterDeals].sort((a, b) => b.weighted - a.weighted).slice(0, 3).reduce((s, d) => s + d.weighted, 0);

const flagged = (flag) => enriched.filter((d) => d.flags.includes(flag));
const risk = (flag) => { const l = flagged(flag); return { count: l.length, amount: round(l.reduce((s, d) => s + d.amount, 0)) }; };
const risks = {
  pastDue: risk('past_due'),
  stale: { ...risk('stale'), days: CONFIG.STALE_DAYS },
  missingAmount: risk('missing_amount'),
  missingCloseDate: risk('missing_close_date'),
  unknownStage: risk('unknown_stage'),
  concentrationTop3: quarterAgg.weighted > 0 ? ratio(top3Weighted / quarterAgg.weighted) : null,
};

// ---------- Week over week ----------
const prev = data.previousSnapshot || null;
const delta = (now, before) => (Number.isFinite(before) ? { now, before, change: round(now - before), pct: before ? ratio((now - before) / before) : null } : null);
const wow = prev ? {
  previousWeekKey: prev.weekKey,
  sameQuarter: prev.quarterLabel === quarter.label,
  quarterWeighted: prev.quarterLabel === quarter.label ? delta(quarter.weighted, prev.quarterWeighted) : null,
  closedWonQTD: prev.quarterLabel === quarter.label ? delta(closedWonQTD, prev.closedWonQTD) : null,
  openAmount: delta(allAgg.amount, prev.openAmount),
  openCount: delta(allAgg.count, prev.openCount),
} : null;

const snapshot = {
  weekKey: p.weekKey, asOf: p.asOf, quarterLabel: quarter.label, quarterWeighted: quarter.weighted,
  openAmount: allAgg.amount, openCount: allAgg.count, closedWonQTD, projected,
};

return [{ json: {
  meta: { ...data.meta, probabilitySource: CONFIG.PROBABILITY_SOURCE, commitProbability: CONFIG.COMMIT_PROBABILITY, pastDueTreatment: CONFIG.PAST_DUE_TREATMENT, overridesApplied: Object.keys(overrides).length },
  periods: p,
  totals: allAgg,
  quarter,
  nextQuarter,
  byPeriod,
  byStage,
  byPipeline,
  byOwner,
  topDeals,
  risks,
  wow,
  snapshot,
} }];

