const SLACK_HOOK = /^https:\/\/hooks\.slack\.com\/services\/[A-Za-z0-9_\-/]+$/;
const destinations = [{ key: 'PRIMARY', envVar: 'SLACK_WEBHOOK_URL' }, { key: 'SECONDARY', envVar: 'SLACK_WEBHOOK_URL_SECONDARY' }]
  .filter((d) => d.key === 'PRIMARY' || env(d.envVar, ''));
if (!EFFECTIVE_DRY_RUN) {
  for (const d of destinations) {
    const url = env(d.envVar, '');
    if (!SLACK_HOOK.test(url) || /YOUR_|PLACEHOLDER|REPLACE_/i.test(url)) throw new Error(`${d.envVar} is missing or is not a valid https://hooks.slack.com/services/... URL.`);
  }
