// ---------- Formatting helpers ----------
const f = $input.first().json;
const SYMBOLS = { USD: '$', EUR: '€', GBP: '£', JPY: '¥', INR: '₹', AUD: 'A$', CAD: 'C$', SGD: 'S$', BDT: '৳' };
const sym = SYMBOLS[CONFIG.CURRENCY_CODE] || `${CONFIG.CURRENCY_CODE} `;
function money(n, compact = true) {
  if (n === null || n === undefined || !Number.isFinite(n)) return '—';
  const sign = n < 0 ? '−' : '';
  const a = Math.abs(n);
  if (compact && a >= 1e9) return `${sign}${sym}${(a / 1e9).toFixed(2)}B`;
  if (compact && a >= 1e6) return `${sign}${sym}${(a / 1e6).toFixed(2)}M`;
  if (compact && a >= 1e4) return `${sign}${sym}${(a / 1e3).toFixed(1)}K`;
  return `${sign}${sym}${Math.round(a).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')}`;
}
const pct = (n, digits = 0) => (n === null || n === undefined || !Number.isFinite(n) ? '—' : `${(n * 100).toFixed(digits)}%`);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // blocks <!channel>, links, mentions
const pad = (s, n, right = false) => { s = String(s); if (s.length > n) s = `${s.slice(0, n - 1)}…`; return right ? s.padStart(n) : s.padEnd(n); };
const arrow = (d) => (!d || d.change === 0 ? '■' : d.change > 0 ? '▲' : '▼');
const deltaText = (d, isMoney = true) => (!d ? '—' : `${arrow(d)} ${isMoney ? money(d.change) : (d.change > 0 ? `+${d.change}` : d.change)}${d.pct !== null ? ` (${d.pct > 0 ? '+' : ''}${pct(d.pct, 1)})` : ''}`);
function dateLabel(iso) {
  try { return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: CONFIG.REPORT_TIMEZONE }); }
  catch (e) { return String(iso).slice(0, 10); }
}
function timeLabel(iso) {
  try { return new Date(iso).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: CONFIG.REPORT_TIMEZONE, timeZoneName: 'short' }); }
  catch (e) { return String(iso).replace('T', ' ').slice(0, 16) + ' UTC'; }
}
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const clip = (s, max = 2900) => (s.length > max ? `${s.slice(0, max - 20)}\n… (truncated)` : s);
const codeTable = (lines) => clip(`\`\`\`\n${lines.join('\n')}\n\`\`\``);

// ---------- Blocks ----------
const q = f.quarter;
const isSample = f.meta.source === 'sandbox_sample';
const blocks = [];
const section = (text) => blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(text) } });
const fields = (list) => blocks.push({ type: 'section', fields: list.slice(0, 10).map((t) => ({ type: 'mrkdwn', text: clip(t, 1900) })) });
const divider = () => blocks.push({ type: 'divider' });
const context = (text) => blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: clip(text, 2900) }] });

blocks.push({ type: 'header', text: { type: 'plain_text', emoji: true, text: `📊 ${CONFIG.REPORT_TITLE} · ${q.label}`.slice(0, 150) } });
context(`Week of *${dateLabel(f.periods.asOf)}* · Snapshot ${timeLabel(f.periods.asOf)} · ${q.daysLeft} days left in quarter${isSample ? ' · :test_tube: *SANDBOX – fictional data*' : ''}`);

fields([
  `*Weighted forecast (${esc(q.label)})*\n${money(q.weighted)}`,
  `*Projected quarter*\n${money(q.projected)}${q.projectedAttainment !== null ? ` · ${pct(q.projectedAttainment)} of target` : ''}`,
  `*Closed won QTD*\n${money(q.closedWonQTD)} · ${plural(q.closedWonCount, 'deal', 'deals')}${q.attainment !== null ? ` · ${pct(q.attainment)}` : ''}`,
  `*Quarter target*\n${q.target !== null ? money(q.target) : 'not set'}${q.gapToTarget !== null ? ` · ${q.gapToTarget > 0 ? `gap ${money(q.gapToTarget)}` : `ahead by ${money(-q.gapToTarget)}`}` : ''}`,
  `*Expected range (P10–P90)*\n${money(q.projectedP10)} – ${money(q.projectedP90)}`,
  `*Commit / Best case*\n${money(q.commit)} / ${money(q.bestCase)}`,
  `*Open pipeline in quarter*\n${money(q.amount)} · ${plural(q.count, 'deal', 'deals')}`,
  `*Coverage ratio*\n${q.targetAlreadyMet ? 'target already met' : q.coverage !== null ? `${q.coverage.toFixed(2)}×` : '—'}`,
]);

if (f.wow) {
  const w = f.wow;
  section([
    `*Week over week* (vs ${esc(w.previousWeekKey)})`,
    `• Weighted forecast: ${w.sameQuarter ? deltaText(w.quarterWeighted) : '_new quarter, no comparison_'}`,
    `• Closed won QTD: ${w.sameQuarter ? deltaText(w.closedWonQTD) : '—'}`,
    `• Total open pipeline: ${deltaText(w.openAmount)}  ·  Open deals: ${deltaText(w.openCount, false)}`,
  ].join('\n'));
}
divider();

section(`*By close period*\n${codeTable([
  `${pad('Period', 18)}${pad('Deals', 6, true)}${pad('Amount', 11, true)}${pad('Weighted', 11, true)}`,
  ...f.byPeriod.map((r) => `${pad(r.label, 18)}${pad(r.count, 6, true)}${pad(money(r.amount), 11, true)}${pad(money(r.weighted), 11, true)}`),
])}`);

section(`*By stage* (probability from ${esc(f.meta.probabilitySource === 'deal_property' ? 'deal probability property' : 'pipeline stage settings')})\n${codeTable([
  `${pad('Stage', 20)}${pad('Prob', 5, true)}${pad('#', 4, true)}${pad('Amount', 10, true)}${pad('Weighted', 10, true)}`,
  ...f.byStage.map((r) => `${pad(`${f.byPipeline.length > 1 ? `${r.pipelineLabel.slice(0, 3)}·` : ''}${r.stageLabel}`, 20)}${pad(pct(r.probability), 5, true)}${pad(r.count, 4, true)}${pad(money(r.amount), 10, true)}${pad(money(r.weighted), 10, true)}`),
])}`);

if (f.byPipeline.length > 1) {
  section(`*By pipeline*\n${codeTable([
    `${pad('Pipeline', 18)}${pad('#', 4, true)}${pad('Open', 10, true)}${pad('Weighted', 10, true)}${pad('In qtr', 10, true)}`,
    ...f.byPipeline.map((r) => `${pad(r.pipelineLabel, 18)}${pad(r.count, 4, true)}${pad(money(r.amount), 10, true)}${pad(money(r.weighted), 10, true)}${pad(money(r.quarterWeighted), 10, true)}`),
  ])}`);
}

if (CONFIG.SHOW_OWNER_BREAKDOWN && f.byOwner.length) {
  section(`*Top owners by weighted forecast (${esc(q.label)})*\n${codeTable([
    `${pad('Owner', 24)}${pad('#', 4, true)}${pad('Amount', 11, true)}${pad('Weighted', 11, true)}`,
    ...f.byOwner.map((r) => `${pad(r.ownerName, 24)}${pad(r.count, 4, true)}${pad(money(r.amount), 11, true)}${pad(money(r.weighted), 11, true)}`),
  ])}`);
}

if (f.topDeals.length) {
  const lines = f.topDeals.map((d, i) => {
