    const linked = CONFIG.HUBSPOT_PORTAL_ID && /^\d+$/.test(d.id) ? `<https://app.hubspot.com/contacts/${CONFIG.HUBSPOT_PORTAL_ID}/record/0-3/${d.id}|${label}>` : `*${label}*`;
    const warn = d.flags.includes('past_due') ? ' :warning: past due' : d.flags.includes('stale') ? ' :hourglass: stale' : '';
    return `${i + 1}. ${linked} — ${money(d.weighted)} weighted (${money(d.amount)} × ${pct(d.probability)}) · ${esc(d.stageLabel)} · closes ${d.closeDate ? dateLabel(d.closeDate) : '—'} · ${esc(d.ownerName)}${warn}`;
