  section(`*Top ${f.topDeals.length} deals driving ${esc(q.label)}*\n${lines.join('\n')}`);
}

const r = f.risks;
const riskLines = [
  r.pastDue.count ? `:warning: *${plural(r.pastDue.count, 'past-due deal', 'past-due deals')}* worth ${money(r.pastDue.amount)} (close date already passed${f.meta.pastDueTreatment === 'current_quarter' ? ', still counted in this quarter' : ', excluded from this quarter'})` : null,
  r.stale.count ? `:hourglass: *${plural(r.stale.count, 'deal', 'deals')}* worth ${money(r.stale.amount)} not updated in ${r.stale.days}+ days` : null,
  r.missingAmount.count ? `:grey_question: *${plural(r.missingAmount.count, 'open deal has', 'open deals have')}* no amount (counted as ${money(0)})` : null,
  r.missingCloseDate.count ? `:calendar: *${plural(r.missingCloseDate.count, 'open deal', 'open deals')}* worth ${money(r.missingCloseDate.amount)} ${r.missingCloseDate.count === 1 ? 'has' : 'have'} no close date` : null,
