divider();
context([
  `*Method:* weighted = Σ amount × stage probability · range = expected ± 1.28σ (independent outcomes) · commit = closed won + deals ≥ ${pct(f.meta.commitProbability)}.`,
  `${f.totals.count} open deals in a ${f.periods.horizonQuarters}-quarter horizon (${money(f.totals.amount)} total, ${money(f.totals.weighted)} weighted)${f.meta.truncated ? ' · :warning: deal cap reached, totals may be incomplete' : ''}.`,
