try { post = $('Slack Block Kit Builder').item.json || {}; } catch (e) { /* lineage unavailable */ }

const err = $json.error || {};
const raw = typeof err === 'string' ? err : (err.message || err.description || 'Slack post failed');
const message = String(raw)
  .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/gi, '[REDACTED_SLACK_WEBHOOK]')
  .replace(/xox[abprs]-[A-Za-z0-9-]+/g, '[REDACTED_SLACK_TOKEN]')
  .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
