return {
  json: {
    status: 'slack_post_failed',
    destination: post.destination || null,
    weekKey: post.weekKey || null,
    httpStatus,
    message,
    hint: HINTS[httpStatus] || 'Check the n8n execution log and status.slack.com.',
    loggedAt: new Date().toISOString(),
  },
};
